import { Group, Mesh, BoxGeometry, CircleGeometry, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, DirectionalLight, Color } from 'three/webgpu';
import { uv, vec2, length, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new Group();
  root.name = 'stat-tile-collection';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const disposables = [];
  const primitiveHandles = [];

  // ---- Machined surface card ----
  const cardW = 1.7;
  const cardH = 1.05;
  const cardD = 0.14;
  const cardGeo = new BoxGeometry(cardW, cardH, cardD, 4, 4, 1);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.surface),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.32
  });
  const card = new Mesh(cardGeo, cardMat);
  card.name = 'stat-tile-card';
  root.add(card);
  disposables.push(cardGeo, cardMat);

  // Thin ink-colored bezel line (subtle machined edge) as slightly recessed inner box
  const bezelGeo = new BoxGeometry(cardW - 0.08, cardH - 0.08, cardD * 0.5, 1, 1, 1);
  const bezelMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.45,
    roughness: 0.6,
    clearcoat: 0.15
  });
  const bezel = new Mesh(bezelGeo, bezelMat);
  bezel.position.z = cardD * 0.51;
  root.add(bezel);
  disposables.push(bezelGeo, bezelMat);

  // ---- Contact shadow (grounded object) ----
  const shadowRadius = Math.max(cardW, cardH) * 0.85;
  const shadowGeo = new CircleGeometry(shadowRadius, 48);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const centeredUv = uv().sub(vec2(0.5, 0.5));
  const dist = length(centeredUv).mul(2.0);
  const falloff = smoothstep(1.0, 0.15, dist);
  shadowMat.colorNode = uniform(new THREE.Color(0x000000));
  shadowMat.opacityNode = falloff.mul(0.5);
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.y = -cardH * 0.55;
  contactShadow.position.z = 0.02;
  root.add(contactShadow);
  disposables.push(shadowGeo, shadowMat);

  // ---- Accent rim light (opposite of key, carries accent hue) ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.85);
  rimLight.position.set(-1.4, 0.8, -1.6);
  root.add(rimLight);
  root.add(rimLight.target);

  // ---- Decorative machined mesh (gear) loaded via GLB ----
  const gearGroup = new Group();
  gearGroup.name = 'stat-tile-gear-accent';
  gearGroup.scale.setScalar(0.32);
  gearGroup.position.set(cardW * 0.28, cardH * 0.22, cardD * 0.65);
  root.add(gearGroup);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (!gltf || !gltf.scene) return;
      const scene = gltf.scene;
      scene.traverse((child) => {
        if (child.isMesh && child.material) {
          child.material.metalness = Math.min(0.55, child.material.metalness ?? 0.5);
          child.material.roughness = Math.max(0.5, child.material.roughness ?? 0.55);
        }
      });
      gearGroup.add(scene);
    }).catch(() => {});
  }

  // ---- Text content (render only spec-provided copy; none invented) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  let zOffset = cardD * 0.52 + 0.001;
  for (const item of items) {
    if (!item?.text) continue;
    const isLabel = item.role === 'card-label' || item.role === 'label' || item.role === 'caption';
    const fontSize = item.typography?.fontSize ?? (isLabel ? 24 : 68);
    const node = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: isLabel ? colors.paper : colors.paper,
      align: 'center',
      letterSpacingPx: isLabel ? 2 : 0
    });
    node.position.set(0, isLabel ? -cardH * 0.2 : cardH * 0.12, zOffset);
    zOffset += 0.0005;
    root.add(node);
    textNodes.push(node);
  }

  // ---- Entrance: weighted-settle + subtle rise-in ----
  root.scale.setScalar(0.94);
  root.position.y -= 0.12;
  const entranceTl = gsap.timeline();
  entranceTl.to(root.position, { y: root.position.y + 0.12, duration: 0.7, ease: 'power3.out' }, 0);
  entranceTl.to(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power2.out' }, 0);
  entranceTl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.45);

  // ---- Cinematic primitives ----
  const parallax = ctx.primitives['parallax-scroll'](root, { intensity: 0.4 });
  primitiveHandles.push(parallax);
  const magnetic = ctx.primitives['magnetic-cursor'](root, { radius: 1.2, strength: 0.35 });
  primitiveHandles.push(magnetic);

  // ---- Interaction handlers ----
  let hoverTl = null;
  const baseY = root.position.y;

  function onHoverStart() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, { y: baseY + 0.15, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(root.rotation, { x: -0.03, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onHoverEnd() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, { y: baseY, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(root.rotation, { x: 0, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onClick() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' })
      .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.18, ease: 'power2.out' });
    ctx.emit('hub-collection.select', { itemId: 'hub-collection-stat-tile' });
  }

  root.userData.handlers = {
    onHoverStart,
    onHoverEnd,
    onClick,
    onPointerEnter: onHoverStart,
    onPointerLeave: onHoverEnd,
    onPointerDown: onClick
  };

  // ---- Cleanup ----
  root.userData.cleanup = function cleanup() {
    entranceTl.kill();
    if (hoverTl) hoverTl.kill();
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    for (const t of textNodes) {
      if (t.geometry) t.geometry.dispose?.();
      if (t.material) t.material.dispose?.();
    }
    gearGroup.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose?.());
        } else {
          child.material?.dispose?.();
        }
      }
    });
    rimLight.dispose?.();
  };

  return root;
}
